const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const query = req.query || {};

// 1. Extract Token from Authorization header (Bearer <token>) or body/query
let rawHeader = headers['authorization'] || headers['Authorization'] || '';
let token = '';

if (typeof rawHeader === 'string' && rawHeader.toLowerCase().startsWith('bearer ')) {
  token = rawHeader.substring(7).trim();
} else if (typeof rawHeader === 'string' && rawHeader.trim().length > 0 && !rawHeader.includes(' ')) {
  token = rawHeader.trim();
} else if (body.token) {
  token = String(body.token).trim();
} else if (query.token) {
  token = String(query.token).trim();
}

if (!token) {
  return [{
    json: {
      hasToken: false,
      statusCode: 401,
      error: "Access denied. Authentication token required. Outsiders are not permitted."
    }
  }];
}

return [{
  json: {
    hasToken: true,
    token: token
  }
}];

const inputData = $input.first().json || {};

if (inputData.error) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or expired authentication token. Outsiders are not permitted."
    }
  }];
}

const claims = inputData.payload || inputData;

if (!claims || !claims.sub) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or malformed authentication token. Please log in again."
    }
  }];
}

const employeeId = String(claims.sub).trim();
const webhookNode = $('Webhook - POST /attendance-punch').first().json || {};
const body = webhookNode.body || {};

const punchType = (body.type || 'IN').toUpperCase().trim();
if (punchType !== 'IN' && punchType !== 'OUT') {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: "Invalid punch type: must be either 'IN' or 'OUT'."
    }
  }];
}

// Calculate IST current time
const now = new Date();
const istString = now.toLocaleString("en-US", { timeZone: "Asia/Kolkata" });
const istDate = new Date(istString);

let hours = istDate.getHours();
const minutes = istDate.getMinutes();
const period = hours >= 12 ? 'PM' : 'AM';
let hours12 = hours % 12;
if (hours12 === 0) hours12 = 12;

const currentTime12H = `${hours12.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')} ${period}`;
const punchTime12H = body.customTime ? String(body.customTime).trim() : currentTime12H;
const location = body.location || 'Office Biometric / Mobile App';
const notes = body.notes || body.note || null;

return [{
  json: {
    valid: true,
    employeeId: employeeId,
    punchType: punchType,
    punchTime12H: punchTime12H,
    location: location,
    notes: notes
  }
}];

const reqInfo = $('Code - Validate Punch Request').first().json || {};
const row = $input.first().json || {};

const employeeId = reqInfo.employeeId;
const punchType = reqInfo.punchType;
const punchTime = reqInfo.punchTime12H;
const location = reqInfo.location;

function timeStringToMinutes(timeStr) {
  if (!timeStr) return 0;
  const clean = timeStr.trim();
  const isPM = /PM$/i.test(clean);
  const isAM = /AM$/i.test(clean);
  const raw = clean.replace(/\s*(AM|PM)$/i, '').trim();
  const parts = raw.split(':');
  let h = parseInt(parts[0], 10);
  const m = parseInt(parts[1] || '0', 10);
  if (isNaN(h) || isNaN(m)) return 0;
  if (isPM && h < 12) h += 12;
  else if (isAM && h === 12) h = 0;
  return h * 60 + m;
}

const punchMinutes = timeStringToMinutes(punchTime);
const nowIso = new Date().toISOString();
const dateStr = nowIso.split('T')[0];
const attendanceId = row.attendance_id || `att-${dateStr}-${employeeId}`;
const punchId = `p-${Date.now()}-${employeeId}`;

if (punchType === 'IN') {
  if (row.has_record_today && row.check_in) {
    return [{
      json: {
        allowed: false,
        statusCode: 400,
        error: `You have already checked in today at ${row.check_in}.`
      }
    }];
  }

  // 1. Strict Cutoff: After 02:30 PM (870 mins), punch-in is CLOSED and employee is directly marked ABSENT
  if (punchMinutes > 870) {
    const sqlQuery = `
      INSERT INTO attendances (
        id, employee_id, date, status, status_label, expected_checkout_time,
        late_allowance_used, is_half_day_case, half_day_reason,
        lunch_duration_minutes, total_duration_minutes, work_duration_minutes, notes
      ) VALUES (
        '${attendanceId}', '${employeeId}', CURRENT_DATE,
        'ABSENT', 'Absent (Punch Closed after 2:30 PM)', '19:00',
        NULL, FALSE, 'Attempted punch-in after 2:30 PM cutoff (${punchTime}). Directly marked as absent.',
        0, 0, 0, 'Attempted punch-in after 2:30 PM cutoff. Directly marked as absent.'
      )
      ON CONFLICT (employee_id, date) DO UPDATE SET
        status = 'ABSENT',
        status_label = 'Absent (Punch Closed after 2:30 PM)',
        notes = 'Attempted punch-in after 2:30 PM cutoff (${punchTime}). Directly marked as absent.';

      INSERT INTO attendance_punches (
        id, attendance_id, employee_id, type, timestamp, time_string, location, note
      ) VALUES (
        '${punchId}', '${attendanceId}', '${employeeId}',
        'IN', CURRENT_TIMESTAMP, '${punchTime}',
        '${location.replace(/'/g, "''")}', 'Blocked: After 2:30 PM cutoff (Marked Absent)'
      );
    `;

    return [{
      json: {
        allowed: true,
        isBlockedAbsent: true,
        employeeId: employeeId,
        attendanceId: attendanceId,
        punchType: 'IN',
        punchTime: punchTime,
        sqlQuery: sqlQuery
      }
    }];
  }

  // Arrival Policy Evaluation:
  // Standard Opening: 10:00 AM (600 mins)
  // Buffer Limit: 10:20 AM (620 mins) -> Stay until 7:30 PM (19:30)
  // Late Allowance Limit: 10:45 AM (645 mins)
  const prevLates = parseInt(row.monthly_lates_used || '0', 10);
  let status = 'ON_TIME';
  let statusLabel = 'On Time';
  let expectedCheckout = '19:00';
  let lateAllowanceUsed = null;
  let isHalfDayCase = false;
  let halfDayReason = null;

  let leaveAdjustmentSql = '';
  if (punchMinutes > 645 || (punchMinutes > 620 && prevLates >= 3)) {
    const halfDayAvail = parseFloat(row.half_day_available || '0');
    const casualAvail = parseFloat(row.casual_available || '0');
    const adjLeaveId = 'lev-adj-' + attendanceId;
    const notifId = 'notif-adj-' + attendanceId;

    if (halfDayAvail >= 0.5) {
      leaveAdjustmentSql = `
        UPDATE leave_balances
        SET used = used + 0.5
        WHERE employee_id = '${employeeId}' AND leave_type = 'HALF_DAY' AND year = EXTRACT(YEAR FROM CURRENT_DATE)::INT;

        INSERT INTO leave_requests (
          id, employee_id, leave_type, duration_type,
          start_date, end_date, days_count, reason,
          status, applied_on, approved_or_rejected_by,
          reviewed_on, comments, whatsapp_notice_acknowledged
        ) VALUES (
          '${adjLeaveId}', '${employeeId}', 'HALF_DAY', 'FIRST_HALF',
          CURRENT_DATE, CURRENT_DATE, 0.5,
          'Auto-adjustment for late arrival past cutoff to protect salary',
          'APPROVED', CURRENT_DATE, 'SYSTEM_SALARY_PROTECTION', CURRENT_DATE,
          'Auto-adjusted from Half-Day Leave balance to protect monthly salary.',
          TRUE
        ) ON CONFLICT (id) DO NOTHING;

        INSERT INTO notifications (
          id, employee_id, category, title, message, action_route, priority, is_read
        ) VALUES (
          '${notifId}', '${employeeId}', 'LEAVE_UPDATE',
          'Salary Protected by Leave Balance',
          'Your late arrival today at ' || '${punchTime}' || ' was automatically adjusted against 0.5 Half-Day Leave. Zero salary deducted.',
          '/salary', 'NORMAL', FALSE
        ) ON CONFLICT (id) DO NOTHING;
      `;
    } else if (casualAvail >= 0.5) {
      leaveAdjustmentSql = `
        UPDATE leave_balances
        SET used = used + 0.5
        WHERE employee_id = '${employeeId}' AND leave_type = 'CASUAL' AND year = EXTRACT(YEAR FROM CURRENT_DATE)::INT;

        INSERT INTO leave_requests (
          id, employee_id, leave_type, duration_type,
          start_date, end_date, days_count, reason,
          status, applied_on, approved_or_rejected_by,
          reviewed_on, comments, whatsapp_notice_acknowledged
        ) VALUES (
          '${adjLeaveId}', '${employeeId}', 'CASUAL', 'FIRST_HALF',
          CURRENT_DATE, CURRENT_DATE, 0.5,
          'Auto-adjustment for late arrival past cutoff (Casual Leave)',
          'APPROVED', CURRENT_DATE, 'SYSTEM_SALARY_PROTECTION', CURRENT_DATE,
          'Half-Day balance was 0. Auto-adjusted from Casual Leave balance to protect monthly salary.',
          TRUE
        ) ON CONFLICT (id) DO NOTHING;

        INSERT INTO notifications (
          id, employee_id, category, title, message, action_route, priority, is_read
        ) VALUES (
          '${notifId}', '${employeeId}', 'LEAVE_UPDATE',
          'Salary Protected by Casual Leave',
          'Your late arrival today at ' || '${punchTime}' || ' was automatically adjusted against 0.5 Casual Leave. Zero salary deducted.',
          '/salary', 'NORMAL', FALSE
        ) ON CONFLICT (id) DO NOTHING;
      `;
    }
  }

  if (punchMinutes <= 600) {
    status = 'ON_TIME';
    statusLabel = 'On Time';
    expectedCheckout = '19:00';
  } else if (punchMinutes <= 620) {
    status = 'WITHIN_BUFFER';
    statusLabel = 'Within Buffer';
    expectedCheckout = '19:30';
  } else if (punchMinutes <= 645) {
    if (prevLates < 3) {
      const allowanceNum = prevLates + 1;
      status = 'LATE';
      statusLabel = `Late (Allowance ${allowanceNum} of 3)`;
      expectedCheckout = '19:30';
      lateAllowanceUsed = allowanceNum;
    } else {
      status = 'HALF_DAY';
      statusLabel = 'Half Day (Exceeded 3 Late Allowances)';
      expectedCheckout = '19:30';
      isHalfDayCase = true;
      halfDayReason = 'Arrival after 10:20 AM and exhausted all 3 monthly late allowances.';
    }
  } else {
    status = 'HALF_DAY';
    if (punchMinutes > 840) {
      statusLabel = 'Half Day (Second Half Arrival)';
      halfDayReason = `Arrival at ${punchTime} during second half window (2:00 PM – 2:30 PM).`;
    } else {
      statusLabel = 'Half Day (After 10:45 AM Cutoff)';
      halfDayReason = `Arrival at ${punchTime} was beyond maximum 10:45 AM cutoff.`;
    }
    expectedCheckout = '19:30';
    isHalfDayCase = true;
  }

  const sqlQuery = `
    INSERT INTO attendances (
      id, employee_id, date, check_in, check_in_timestamp,
      status, status_label, expected_checkout_time,
      late_allowance_used, is_half_day_case, half_day_reason,
      lunch_duration_minutes, total_duration_minutes, work_duration_minutes
    ) VALUES (
      '${attendanceId}', '${employeeId}', CURRENT_DATE,
      '${punchTime}', CURRENT_TIMESTAMP,
      '${status}', '${statusLabel.replace(/'/g, "''")}', '${expectedCheckout}',
      ${lateAllowanceUsed !== null ? lateAllowanceUsed : 'NULL'},
      ${isHalfDayCase ? 'TRUE' : 'FALSE'},
      ${halfDayReason ? `'${halfDayReason.replace(/'/g, "''")}'` : 'NULL'},
      60, 0, 0
    )
    ON CONFLICT (employee_id, date) DO UPDATE SET
      check_in = EXCLUDED.check_in,
      check_in_timestamp = EXCLUDED.check_in_timestamp,
      status = EXCLUDED.status,
      status_label = EXCLUDED.status_label,
      expected_checkout_time = EXCLUDED.expected_checkout_time,
      late_allowance_used = EXCLUDED.late_allowance_used,
      is_half_day_case = EXCLUDED.is_half_day_case,
      half_day_reason = EXCLUDED.half_day_reason;

    INSERT INTO attendance_punches (
      id, attendance_id, employee_id, type, timestamp, time_string, location, note
    ) VALUES (
      '${punchId}', '${attendanceId}', '${employeeId}',
      'IN', CURRENT_TIMESTAMP, '${punchTime}',
      '${location.replace(/'/g, "''")}', '${statusLabel.replace(/'/g, "''")}'
    );

    ${leaveAdjustmentSql}
  `;

  return [{
    json: {
      allowed: true,
      employeeId: employeeId,
      attendanceId: attendanceId,
      punchType: 'IN',
      sqlQuery: sqlQuery
    }
  }];
} else {
  // Punch OUT
  if (!row.has_record_today || !row.check_in) {
    return [{
      json: {
        allowed: false,
        statusCode: 400,
        error: 'Cannot punch out without punching in first.'
      }
    }];
  }

  if (row.check_out) {
    return [{
      json: {
        allowed: false,
        statusCode: 400,
        error: `You have already punched out today at ${row.check_out}.`
      }
    }];
  }

  const checkInMin = timeStringToMinutes(row.check_in);
  const grossDuration = Math.max(0, punchMinutes - checkInMin);
  const lunchDuration = 60;
  const netWorkDuration = Math.max(0, grossDuration - lunchDuration);
  const expectedOutMin = timeStringToMinutes(row.expected_checkout_time || '19:00');
  const overtimeMin = Math.max(0, punchMinutes - expectedOutMin);

  // Policy: Overtime starts after 07:30 PM (1170 minutes from midnight)
  const otThresholdMin = 1170; // 19:30
  let isOvertime = false;
  let otDurationMinutes = 0;
  let otHoursFormatted = '';
  let otInsertSql = '';

  if (punchMinutes > otThresholdMin) {
    isOvertime = true;
    otDurationMinutes = punchMinutes - otThresholdMin;
    const otHours = Math.floor(otDurationMinutes / 60);
    const otRemainingMins = otDurationMinutes % 60;
    otHoursFormatted = (otHours > 0 ? `${otHours}h ` : '') + (otRemainingMins > 0 || otHours === 0 ? `${otRemainingMins}m` : '').trim();

    const otId = `ot-${dateStr}-${employeeId}`;
    const notifId = `notif-${Date.now()}-${employeeId}`;

    otInsertSql = `
      INSERT INTO overtime_records (
        id, employee_id, date, start_time, end_time,
        duration_minutes, hours_formatted, reason, approver,
        status, compensation_method, reimbursement_status,
        early_leave_status, notes
      ) VALUES (
        '${otId}',
        '${employeeId}',
        CURRENT_DATE,
        '07:30 PM',
        '${punchTime}',
        ${otDurationMinutes},
        '${otHoursFormatted}',
        'Auto-logged shift extension beyond 07:30 PM',
        'Admin',
        'PENDING',
        'EARLY_LEAVE_ADJUSTMENT',
        'NOT_APPLICABLE',
        'NOT_APPLICABLE',
        'Auto-generated on punch out. Pending admin review for weekly early-leave adjustment credit.'
      )
      ON CONFLICT (id) DO UPDATE SET
        end_time = EXCLUDED.end_time,
        duration_minutes = EXCLUDED.duration_minutes,
        hours_formatted = EXCLUDED.hours_formatted,
        updated_at = CURRENT_TIMESTAMP;

      INSERT INTO notifications (
        id, employee_id, category, title, message, action_route, priority, is_read
      ) VALUES (
        '${notifId}',
        '${employeeId}',
        'OVERTIME_UPDATE',
        'Overtime Logged (${otHoursFormatted})',
        'You clocked out at ${punchTime} (${otHoursFormatted} overtime). Auto-submitted to Admin as PENDING for early-leave compensation.',
        '/(tabs)/overtime',
        'NORMAL',
        FALSE
      );
    `;
  }

  const sqlQuery = `
    UPDATE attendances SET
      check_out = '${punchTime}',
      check_out_timestamp = CURRENT_TIMESTAMP,
      total_duration_minutes = ${grossDuration},
      work_duration_minutes = ${netWorkDuration},
      overtime_minutes = ${overtimeMin}
    WHERE id = '${attendanceId}';

    INSERT INTO attendance_punches (
      id, attendance_id, employee_id, type, timestamp, time_string, location, note
    ) VALUES (
      '${punchId}', '${attendanceId}', '${employeeId}',
      'OUT', CURRENT_TIMESTAMP, '${punchTime}',
      '${location.replace(/'/g, "''")}', 'Shift ended'
    );

    ${otInsertSql}
  `;

  return [{
    json: {
      allowed: true,
      employeeId: employeeId,
      attendanceId: attendanceId,
      punchType: 'OUT',
      isOvertime: isOvertime,
      otDurationMinutes: otDurationMinutes,
      otHoursFormatted: otHoursFormatted,
      sqlQuery: sqlQuery
    }
  }];
}

const items = $input.all();
const data = (items.length > 0 && items[0].json) ? items[0].json : {};
const record = data.record || {};
const punches = Array.isArray(data.punches) ? data.punches : [];
const punchRuleData = $('Code - Evaluate Punch Rules & Prepare SQL').first().json || {};

if (punchRuleData.isBlockedAbsent) {
  return [{
    json: {
      success: false,
      statusCode: 403,
      error: `Punch-in is closed after 02:30 PM. You have been directly marked as Absent for today (${punchRuleData.punchTime}).`,
      record: {
        id: record.id || `att-${record.date}-${record.employee_id}`,
        employeeId: record.employee_id,
        date: record.date,
        checkIn: null,
        checkOut: null,
        status: 'ABSENT',
        statusLabel: 'Absent (Punch Closed after 2:30 PM)',
        expectedCheckOutTime: '19:00',
        workDurationMinutes: 0,
        totalDurationMinutes: 0,
        lunchDurationMinutes: 0,
        lateAllowanceUsed: null,
        isHalfDayCase: false,
        isCheckedIn: false,
        isCheckedOut: false,
        punches: punches,
        notes: 'Attempted punch-in after 2:30 PM cutoff. Directly marked as absent.'
      }
    }
  }];
}

const isCheckedIn = !!record.check_in;
const isCheckedOut = !!record.check_out;

let message = isCheckedOut 
  ? "Punched out successfully. Shift ended." 
  : "Punched in successfully. Have a productive day!";

if (punchRuleData.isOvertime) {
  message = `Punched out at ${record.check_out}. Overtime of ${punchRuleData.otHoursFormatted} automatically logged as PENDING for admin approval.`;
}

return [{
  json: {
    success: true,
    statusCode: 200,
    message: message,
    record: {
      id: record.id,
      employeeId: record.employee_id,
      date: record.date,
      checkIn: record.check_in || null,
      checkOut: record.check_out || null,
      status: record.status || 'PENDING',
      statusLabel: record.status_label || (isCheckedIn ? 'Checked In' : 'Awaiting Punch'),
      expectedCheckOutTime: record.expected_check_out_time || '19:00',
      workDurationMinutes: parseInt(record.work_duration_minutes || '0', 10),
      totalDurationMinutes: parseInt(record.total_duration_minutes || '0', 10),
      lunchDurationMinutes: parseInt(record.lunch_duration_minutes || '60', 10),
      lateAllowanceUsed: record.late_allowance_used || null,
      isHalfDayCase: !!record.is_half_day_case,
      isCheckedIn: isCheckedIn,
      isCheckedOut: isCheckedOut,
      punches: punches,
      notes: record.notes || null
    },
    overtime: punchRuleData.isOvertime ? {
      recorded: true,
      durationMinutes: punchRuleData.otDurationMinutes,
      hoursFormatted: punchRuleData.otHoursFormatted,
      status: "PENDING",
      compensationMethod: "EARLY_LEAVE_ADJUSTMENT"
    } : null
  }
}];

